import json
from dataclasses import asdict, dataclass
from datetime import datetime, timezone
from decimal import Decimal

@dataclass
class Order:
    id: int
    total: Decimal
    created: datetime
    tags: set

def to_json(o):
    if isinstance(o, datetime):
        return o.isoformat()
    if isinstance(o, Decimal):
        return str(o)
    if isinstance(o, set):
        return sorted(o)
    raise TypeError(f"{type(o).__name__} is not JSON serializable")

o = Order(1, Decimal("19.90"), datetime(2025, 3, 1, 12, tzinfo=timezone.utc), {"b", "a"})
print(json.dumps(asdict(o), default=to_json))
# {"id": 1, "total": "19.90", "created": "2025-03-01T12:00:00+00:00", "tags": ["a", "b"]}

import json
from decimal import Decimal

def no_duplicates(pairs):
    keys = [k for k, _ in pairs]
    dupes = {k for k in keys if keys.count(k) > 1}
    if dupes:
        raise ValueError(f"duplicate keys: {sorted(dupes)}")
    return dict(pairs)

text = '{"price": 19.90, "qty": 3}'
print(json.loads(text))                        # {'price': 19.9, 'qty': 3}
print(json.loads(text, parse_float=Decimal))   # {'price': Decimal('19.90'), 'qty': 3}

print(json.loads('{"a": 1, "a": 2}'))          # {'a': 2}
try:
    json.loads('{"a": 1, "a": 2}', object_pairs_hook=no_duplicates)
except ValueError as e:
    print(e)                                   # duplicate keys: ['a']

point = lambda d: (d["x"], d["y"]) if d.keys() == {"x", "y"} else d
print(json.loads('{"p": {"x": 1, "y": 2}}', object_hook=point))  # {'p': (1, 2)}

import io
import json
from datetime import date
from enum import Enum

class Color(Enum):
    RED = "red"

class AppEncoder(json.JSONEncoder):
    def default(self, o):
        if isinstance(o, date):
            return o.isoformat()
        if isinstance(o, Enum):
            return o.value
        return super().default(o)    # raises TypeError

data = {"day": date(2025, 1, 31), "color": Color.RED}
print(json.dumps(data, cls=AppEncoder))  # {"day": "2025-01-31", "color": "red"}

out = io.StringIO()
enc = AppEncoder(separators=(",", ":"))
rows = [{"n": i} for i in range(3)]
for chunk in enc.iterencode(rows):       # streamed in pieces
    out.write(chunk)
print(out.getvalue())                    # [{"n":0},{"n":1},{"n":2}]

import json

records = [{"id": 1, "msg": "hi\nthere"}, {"id": 2, "msg": "bye"}]
with open("events.jsonl", "w", encoding="utf-8") as f:
    for r in records:
        f.write(json.dumps(r) + "\n")       # escaped \n keeps one line
    f.write("{broken\n")

def read_jsonl(path):
    with open(path, encoding="utf-8") as f:
        for n, line in enumerate(f, 1):
            if not line.strip():
                continue
            try:
                yield json.loads(line)
            except json.JSONDecodeError as e:
                print(f"line {n}: {e.msg}")
print([r["id"] for r in read_jsonl("events.jsonl")])
