import json

def strict_loads(text, max_len=100_000):
    if len(text) > max_len:
        raise ValueError("body too large")
    def reject_constant(name):
        raise ValueError(f"{name} not allowed")
    def short_int(s):
        if len(s) > 30:
            raise ValueError("number too long")
        return int(s)
    try:
        return json.loads(text, parse_constant=reject_constant, parse_int=short_int)
    except RecursionError:
        raise ValueError("nesting too deep") from None

for body in ['{"n": 1}', '{"x": NaN}', "[" * 100_000 + "]" * 100_000,
             "9" * 50, "9" * 5000]:
    try:
        print(strict_loads(body, max_len=10**6))
    except ValueError as e:
        print("rejected:", str(e)[:24])
